/*
 * Vite plugin: robots.txt with the site's absolute sitemap URL (VITE_SITE_URL), emitted
 * in the build and served by the dev server. The sitemap itself is generated by the API
 * (GET /sitemap.xml, so new cars appear in it at once): the dev server proxies it (see
 * `server.proxy` in vite.config.js) and production routes /sitemap.xml to the API.
 */
export function robotsTxt(siteUrl) {
  return [
    'User-agent: *',
    // Account, admin and booking areas, and the token links of the e-mails.
    'Disallow: /admin',
    'Disallow: /espace',
    'Disallow: /reserver/',
    'Disallow: /verifier-email',
    'Disallow: /reinitialiser-mot-de-passe',
    'Disallow: /design',
    'Allow: /',
    '',
    `Sitemap: ${siteUrl.replace(/\/$/, '')}/sitemap.xml`,
    '',
  ].join('\n')
}

export default function seoFiles(siteUrl) {
  return {
    name: 'tomobilti-seo-files',
    configureServer(server) {
      server.middlewares.use('/robots.txt', (_request, response) => {
        response.setHeader('Content-Type', 'text/plain; charset=utf-8')
        response.end(robotsTxt(siteUrl))
      })
    },
    generateBundle() {
      this.emitFile({ type: 'asset', fileName: 'robots.txt', source: robotsTxt(siteUrl) })
    },
  }
}
